import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

base='http://localhost:8080'
token=None

def request(path, method='GET', body=None):
    global token
    attempts=0
    while True:
        attempts += 1
        headers={'Accept':'application/json'}
        data=None
        if token and path "'!= '"'/token':
            headers['Authorization']='Bearer '+token
        if body is not None:
            data=json.dumps(body).encode()
            headers['Content-Type']='application/json'
        req=urllib.request.Request(base+path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=20) as res:
                return json.loads(res.read().decode())
        except urllib.error.HTTPError as e:
            raw=e.read().decode(errors='replace')
            try: payload=json.loads(raw)
            except Exception: payload={}
            if e.code == 401 and path "'!= '"'/token':
                print('token renewal', flush=True)
                token=None
                fetch_token()
                continue
            if e.code == 429:
                wait=e.headers.get('Retry-After')
                if wait is None:
                    wait=payload.get('retry_after', payload.get('retry_after_seconds', 1))
                try: delay=float(wait)
                except Exception: delay=1
                delay=max(delay, 0.05)
                print(f'rate limited; wait {delay}s', flush=True)
                time.sleep(delay)
                continue
            if attempts < 12 and e.code >= 500:
                delay=min(2**(attempts-1), 30)
                print(f'HTTP {e.code}; retrying in {delay}s', flush=True)
                time.sleep(delay)
                continue
            raise RuntimeError(f'{method} {path} failed HTTP {e.code}: {raw[:500]}')
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as e:
            if attempts < 12:
                delay=min(2**(attempts-1), 30)
                print(f'{type(e).__name__}; retrying in {delay}s', flush=True)
                time.sleep(delay)
                continue
            raise

def fetch_token():
    global token
    token=[REDACTED_SECRET]'/token', 'POST')['token']

fetch_token()
seen=set(); duplicates=0; qualified=[]
page=1; total_pages=None
while True:
    data=request(f'/orders?page={page}')
    if data['page'] "'!= page:
        raise RuntimeError(f'"'page mismatch requested {page}, got {data[\"page\"]}')
    if total_pages is None: total_pages=data['total_pages']
    elif total_pages "'!= data['"'total_pages']: raise RuntimeError('total_pages changed')
    for o in data['items']:
        if o['id'] in seen:
            duplicates += 1
            continue
        seen.add(o['id'])
        stamp=datetime.fromisoformat(o['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
        if o['status'] == 'shipped' and datetime(2025,3,1,tzinfo=timezone.utc) <= stamp < datetime(2025,6,1,tzinfo=timezone.utc):
            qualified.append(o)
    print(f'page {page}/{total_pages}: unique listings {len(seen)}, qualified {len(qualified)}', flush=True)
    if data['next'] is None:
        if page "'!= total_pages: raise RuntimeError('"'next null before total_pages')
        break
    page += 1

customers={}
def customer(cid):
    if cid not in customers:
        customers[cid]=request('/customers/'+urllib.parse.quote(str(cid), safe=''))
    return customers[cid]

by_region={r:0 for r in ('north','south','east','west')}
for o in qualified:
    c=customer(o['customer_id'])
    cents=int((Decimal(o['amount_cents']) * (Decimal(100)-Decimal(c['discount_pct'])) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[c['region']] += cents
result={'total_cents':sum(by_region.values()), 'order_count':len(qualified), 'duplicates_skipped':duplicates, 'by_region':by_region}
